            Exercise.CodeChallenge(id = "mit_6_100l_2022_s014_e01", prompt = "Quelle fréquence est obtenue pour la lettre a ?", codeSnippet = "freq = {}\nfor c in \"banana\":\n    freq[c] = freq.get(c, 0) + 1\nprint(freq[\"a\"])", options = listOf("6", "3", "2", "1"), correctOptionIndex = 1, explanation = "Le texte banana contient trois a. get(c,0) fournit zéro à la première rencontre, puis la valeur est augmentée.", hint = "Tiens un compteur séparé par clé."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s014_e02", prompt = "L’affectation à la clé existante ajoute-t-elle une entrée ?", codeSnippet = "notes = {\"Awa\": 7}\nnotes[\"Awa\"] = 9\nprint(len(notes), notes[\"Awa\"])", options = listOf("1 9", "2 9", "1 7", "2 7"), correctOptionIndex = 0, explanation = "La clé Awa existe déjà : sa valeur devient 9 et le dictionnaire conserve une seule entrée.", hint = "Une clé est unique."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s014_e03", prompt = "Le test in porte-t-il sur les clés ou sur les valeurs ?", codeSnippet = "d = {\"nord\": 3}\nprint(\"nord\" in d, 3 in d)", options = listOf("True True", "False True", "False False", "True False"), correctOptionIndex = 3, explanation = "Le dictionnaire contient la clé nord, mais 3 n’est qu’une valeur.", hint = "Pour consulter les valeurs, il faudrait employer d.values()."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s014_e04", prompt = "Quelle clé peut servir directement dans un dictionnaire Python ?", options = listOf("Le dictionnaire {2: 3}", "La liste [[2], [3]]", "Le tuple (2, 3)", "La liste [2, 3]"), correctOptionIndex = 2, explanation = "Un tuple dont les éléments sont hachables l’est aussi. Les listes et dictionnaires proposés sont mutables et non hachables.", hint = "L’immuabilité du conteneur ne suffit pas si ses éléments ne sont pas hachables.")
        ),
        objective = "Mettre à jour un dictionnaire et compter des occurrences.",
        learningNotes = "Un dictionnaire associe chaque clé unique à une valeur. Il évite de synchroniser plusieurs listes parallèles : notes['Awa'] trouve directement l'information correspondante. Affecter une valeur à une clé existante remplace cette valeur ; une nouvelle clé ajoute une entrée. Le test k in d cherche parmi les clés, pas parmi les valeurs. Pour compter les lettres, on peut initialiser une clé absente à zéro puis augmenter son compteur. Les clés doivent être hachables : un tuple d'entiers convient, une liste ne convient pas. Les valeurs peuvent être des listes ou d'autres dictionnaires. Python moderne conserve l'ordre d'insertion ; cela ne signifie pas que les clés sont triées et un algorithme d'association n'a souvent pas besoin de dépendre de cet ordre.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/pages/lecture-14-dictionaries/", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec14.pdf", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec14_code.py"),
        requiresPreviousLesson = true,
