        sessionKind = "lesson"
    )

    private fun lesson015() = Lesson(
        id = "mit_6_100l_2022_s015",
        title = "Réduire un calcul par récursion",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s015_e01", prompt = "Quelle valeur retourne ce calcul récursif ?", codeSnippet = "def fact(n):\n    if n == 0:\n        return 1\n    return n*fact(n-1)\nprint(fact(5))", options = listOf("120", "24", "15", "1"), correctOptionIndex = 0, explanation = "fact(5)=5*4*3*2*1*fact(0), et fact(0)=1.", hint = "Déroule jusqu’au cas de base puis remonte."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s015_e02", prompt = "Quel nombre d’appels est compté, en incluant celui du cas de base ?", codeSnippet = "def appels(n):\n    if n == 0:\n        return 1\n    return 1 + appels(n-1)\nprint(appels(3))", options = listOf("3", "5", "1", "4"), correctOptionIndex = 3, explanation = "Les appels portent sur n=3,2,1,0, donc quatre exécutions.", hint = "N’oublie pas l’appel qui ne récursive plus."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s015_e03", prompt = "Pour n entier positif, quelle transformation rapproche un appel du cas n==0 ?", options = listOf("Appeler avec n.", "Appeler avec 2*n.", "Appeler avec n-1.", "Appeler avec n+1."), correctOptionIndex = 2, explanation = "La suite des entiers positifs diminue de un jusqu’à zéro. Les autres propositions n’assurent pas ce progrès.", hint = "Cherche une mesure entière qui décroît strictement."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s015_e04", prompt = "Quelle puissance est calculée ?", codeSnippet = "def puissance(n, p):\n    if p == 0:\n        return 1\n    return n*puissance(n, p-1)\nprint(puissance(3, 4))", options = listOf("64", "81", "27", "12"), correctOptionIndex = 1, explanation = "Le cas p=0 retourne 1, puis quatre multiplications par 3 produisent 81.", hint = "L’exposant diminue à chaque appel.")
        ),
        objective = "Identifier un cas de base et suivre les retours d’appels.",
        learningNotes = "Une fonction récursive résout un problème en appelant une version plus petite de ce même problème. Deux éléments sont nécessaires : un cas de base résolu directement et une progression qui finit par l'atteindre. Pour n entier non négatif, n! vaut 1 si n=0, sinon n fois (n-1)!. L'appel initial attend le résultat des appels plus profonds ; les multiplications se terminent ensuite en remontant. Chaque appel possède ses paramètres locaux. Une formule récursive doit respecter son domaine : diminuer un entier négatif en espérant atteindre zéro ne termine pas. La récursion ne rend pas automatiquement le calcul plus rapide ; elle offre une structure de raisonnement, avec un coût de pile et parfois des calculs répétés.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/pages/lecture-15-recursion/", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec15.pdf", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec15_code.py"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 15,
        sourceTitle = "Lecture 15: Recursion",
        sessionKind = "lesson"
    )

    private fun lesson016() = Lesson(
        id = "mit_6_100l_2022_s016",
        title = "Récursion sur séquences et mémorisation",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s016_e01", prompt = "Le palindrome est-il reconnu après réduction des extrémités ?", codeSnippet = "def palindrome(s):\n    if len(s) <= 1:\n        return True\n    return s[0] == s[-1] and palindrome(s[1:-1])\nprint(palindrome(\"radar\"), palindrome(\"rame\"))", options = listOf("True True", "False True", "False False", "True False"), correctOptionIndex = 3, explanation = "radar réduit à ada puis d ; les extrémités concordent. Pour rame, r et e diffèrent dès le début.", hint = "Teste la longueur avant de consulter les extrémités."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s016_e02", prompt = "Quel résultat donne l’aplatissement de ces blocs ?", codeSnippet = "def aplatir(blocs):\n    if not blocs:\n        return []\n    return blocs[0] + aplatir(blocs[1:])\nprint(aplatir([[1], [2, 3], []]))", options = listOf("[3, 2, 1]", "[1, [2, 3]]", "[1, 2, 3]", "[[1], [2, 3]]"), correctOptionIndex = 2, explanation = "Le premier bloc [1] est concaténé à [2,3], puis au résultat vide.", hint = "Le cas de base est une liste vide."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s016_e03", prompt = "Quelle valeur de Fibonacci est mémorisée pour 6 ?", codeSnippet = "def fib(n, memo):\n    if n not in memo:\n        memo[n] = fib(n-1, memo) + fib(n-2, memo)\n    return memo[n]\nprint(fib(6, {1: 1, 2: 1}))", options = listOf("6", "8", "5", "13"), correctOptionIndex = 1, explanation = "Les valeurs pour 1 à 6 sont 1,1,2,3,5,8. Le dictionnaire évite les recalculs des clés déjà présentes.", hint = "Chaque nouvelle valeur dépend des deux précédentes."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s016_e04", prompt = "Pourquoi s[1:] peut-il modifier le coût d’une fonction récursive ?", options = listOf("La tranche crée une nouvelle séquence dont les éléments doivent être copiés.", "Une tranche est toujours une vue sans copie.", "La tranche supprime automatiquement tous les appels.", "La tranche trie les éléments."), correctOptionIndex = 0, explanation = "Dans une suite d’appels, copier n-1 puis n-2 éléments, etc., peut cumuler un coût quadratique.", hint = "Additionne le travail effectué à chaque profondeur.")
        ),
        objective = "Décomposer une séquence et éviter de recalculer des sous-problèmes.",
        learningNotes = "La réduction récursive peut porter sur une chaîne ou une liste. Pour sommer une liste, le cas vide retourne zéro ; sinon le premier élément s'ajoute à la somme du reste. Pour un palindrome, on compare les extrémités puis on examine l'intérieur. Le cas de longueur zéro ou un doit être accepté avant d'accéder aux indices. Une liste de listes peut être aplatie en concaténant son premier bloc avec le résultat obtenu sur les blocs restants. Cette construction crée des copies et n'est pas gratuite. La mémorisation répond à un autre problème : pour Fibonacci, un dictionnaire conserve les valeurs déjà calculées. Chaque sous-problème absent est résolu une fois, puis les appels suivants réutilisent sa valeur.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/pages/lecture-16-recursion-on-non-numerics/", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec16.pdf", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec16_code.py"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 16,
        sourceTitle = "Lecture 16: Recursion on Non-Numerics",
        sessionKind = "lesson"
    )

    private fun lesson017() = Lesson(
        id = "mit_6_100l_2022_s017",
        title = "Définir une classe et créer ses instances",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s017_e01", prompt = "Quelles coordonnées propres aux deux instances sont affichées ?", codeSnippet = "class Point:\n    def __init__(self, x):\n        self.x = x\np = Point(1)\nq = Point(1)\np.x = 4\nprint(p.x, q.x)", options = listOf("1 1", "1 4", "4 1", "4 4"), correctOptionIndex = 2, explanation = "p et q sont créés séparément. La modification de p.x ne change pas q.x.", hint = "Repère les deux appels au constructeur."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s017_e02", prompt = "Quel nouvel état produit la méthode ?", codeSnippet = "class Compteur:\n    def __init__(self, valeur):\n        self.valeur = valeur\n    def avance(self, pas):\n        self.valeur += pas\nc = Compteur(3)\nc.avance(4)\nprint(c.valeur)", options = listOf("None", "7", "3", "4"), correctOptionIndex = 1, explanation = "self désigne c ; son attribut valeur passe de 3 à 3+4=7.", hint = "L’appel c.avance transmet c implicitement."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s017_e03", prompt = "Quelle distance sépare les deux points ?", codeSnippet = "class Point:\n    def __init__(self, x, y):\n        self.x, self.y = x, y\n    def distance(self, autre):\n        return ((self.x-autre.x)**2 + (self.y-autre.y)**2)**0.5\nprint(Point(1, 2).distance(Point(4, 6)))", options = listOf("5.0", "7", "25", "1.0"), correctOptionIndex = 0, explanation = "Les différences sont 3 et 4 ; la racine de 9+16 vaut 5.", hint = "Applique le théorème de Pythagore aux différences."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s017_e04", prompt = "Dans p.methode(8), à quoi self est-il relié durant l’appel ?", options = listOf("À l’entier 8.", "À la chaîne \"self\".", "À toutes les instances simultanément.", "À l’instance p."), correctOptionIndex = 3, explanation = "Une méthode liée reçoit l’instance sur laquelle elle est appelée comme premier argument implicite.", hint = "Sépare objet récepteur et argument explicite.")
        ),
        objective = "Relier attributs, méthodes et objet reçu dans self.",
        learningNotes = "Une classe définit un nouveau type d'objet en regroupant des données et des opérations. Une instance de Point peut conserver ses propres coordonnées x et y. La méthode __init__ initialise les attributs de cette instance ; self désigne l'objet sur lequel la méthode agit. Lors de p.deplacer(2), Python transmet p comme premier argument et 2 comme déplacement. Deux créations Point(...) produisent deux instances distinctes, alors que q=p crée un alias. Une méthode peut lire ou modifier un attribut sans exposer les détails du calcul à son utilisateur. Pour une distance, les différences de coordonnées sont élevées au carré puis additionnées avant la racine. Le contrat précise les types acceptés et la signification de chaque résultat.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/pages/lecture-17-python-classes/", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec17.pdf", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec17_code.py"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 17,
        sourceTitle = "Lecture 17: Python Classes",
        sessionKind = "lesson"
    )

    private fun lesson018() = Lesson(
        id = "mit_6_100l_2022_s018",
        title = "Donner une interface aux objets",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s018_e01", prompt = "Quelle représentation est affichée pour cet objet ?", codeSnippet = "class Point:\n    def __init__(self, x, y):\n        self.x, self.y = x, y\n    def __str__(self):\n        return f\"<{self.x};{self.y}>\"\nprint(Point(2, 5))", options = listOf("Point", "<2;5>", "(2, 5)", "2 5"), correctOptionIndex = 1, explanation = "print utilise la chaîne retournée par __str__, construite ici avec les deux coordonnées.", hint = "La méthode retourne le texte ; elle ne l’affiche pas elle-même."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s018_e02", prompt = "Quelle fraction non simplifiée représente la somme ?", codeSnippet = "class Fraction:\n    def __init__(self, n, d):\n        self.n, self.d = n, d\n    def __add__(self, autre):\n        return Fraction(self.n*autre.d + autre.n*self.d, self.d*autre.d)\n    def __str__(self):\n        return f\"{self.n}/{self.d}\"\nprint(Fraction(1, 2) + Fraction(1, 5))", options = listOf("7/10", "3/7", "2/10", "1/10"), correctOptionIndex = 0, explanation = "1/2+1/5=(1*5+1*2)/(2*5)=7/10. __add__ retourne une nouvelle Fraction.", hint = "Utilise un dénominateur commun."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s018_e03", prompt = "Que doit retourner __str__ pour que print(objet) fonctionne normalement ?", options = listOf("Un entier obligatoire.", "La valeur None.", "L’objet lui-même sans conversion.", "Une chaîne de caractères."), correctOptionIndex = 3, explanation = "Le protocole attend une str. Retourner un autre type provoque une erreur lors de sa conversion en texte.", hint = "Le résultat décrit l’objet pour un lecteur."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s018_e04", prompt = "Le centre conservé par composition est-il partagé ici ?", codeSnippet = "class Point:\n    def __init__(self, x):\n        self.x = x\nclass Cercle:\n    def __init__(self, centre):\n        self.centre = centre\ncentre = Point(1)\np = Cercle(centre)\np.centre.x = 9\nprint(centre.x)", options = listOf("None", "0", "9", "1"), correctOptionIndex = 2, explanation = "centre et p.centre référencent le même objet Point. La modification par p.centre est donc visible dans centre.", hint = "L’affectation d’un objet ne le clone pas.")
        ),
        objective = "Définir représentation, opérations et composition d’objets.",
        learningNotes = "Les méthodes spéciales relient un type personnalisé aux opérations usuelles de Python. __str__ doit retourner une chaîne pour l'affichage ; __add__ peut construire un nouvel objet représentant une somme. Pour deux fractions a/b et c/d, la somme a*d+c*b sur b*d préserve la valeur, même sans simplification. Le dénominateur doit rester non nul. La composition permet à un objet Cercle de conserver un objet Point comme centre et d'utiliser sa méthode de distance. Ce lien peut partager un objet mutable : modifier le centre peut déplacer le cercle. L'interface doit préciser si elle partage ou copie les objets reçus et si une opération produit une nouvelle instance ou transforme l'instance existante.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/pages/lecture-18-more-python-class-methods/", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec18.pdf", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec18_code.py"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 18,
        sourceTitle = "Lecture 18: More Python Class Methods",
        sessionKind = "lesson"
    )

    private fun lesson019() = Lesson(
        id = "mit_6_100l_2022_s019",
        title = "Étendre un type par héritage",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s019_e01", prompt = "Quelle méthode est choisie pour l’objet enfant ?", codeSnippet = "class Animal:\n    def parler(self):\n        return \"animal\"\nclass Chien(Animal):\n    def parler(self):\n        return \"chien\"\nprint(Chien().parler())", options = listOf("chien", "animal", "animal chien", "None"), correctOptionIndex = 0, explanation = "La recherche trouve parler dans Chien avant de remonter à Animal.", hint = "La redéfinition la plus proche de l’instance est utilisée."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s019_e02", prompt = "L’enfant est-il aussi reconnu comme instance du parent ?", codeSnippet = "class Parent:\n    pass\nclass Enfant(Parent):\n    pass\nprint(isinstance(Enfant(), Parent))", options = listOf("False", "Parent", "Enfant", "True"), correctOptionIndex = 3, explanation = "L’héritage établit la relation de sous-type ; isinstance prend en compte cette hiérarchie.", hint = "Le test ne se limite pas à l’égalité exacte des types."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s019_e03", prompt = "Quel état commun est initialisé par super ?", codeSnippet = "class Personne:\n    def __init__(self, age):\n        self.age = age\nclass Eleve(Personne):\n    def __init__(self, nom, age):\n        super().__init__(age)\n        self.nom = nom\ne = Eleve(\"Awa\", 6)\nprint(e.age, e.nom)", options = listOf("6 None", "Awa 6", "6 Awa", "0 Awa"), correctOptionIndex = 2, explanation = "Le constructeur parent reçoit 6 et initialise age ; le constructeur enfant ajoute nom.", hint = "Suis les paramètres transmis au constructeur parent."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s019_e04", prompt = "Quelle valeur est partagée et quelle valeur est masquée ?", codeSnippet = "class Produit:\n    taux = 2\na, b = Produit(), Produit()\na.taux = 9\nprint(a.taux, b.taux, Produit.taux)", options = listOf("9 9 2", "9 2 2", "9 9 9", "2 2 2"), correctOptionIndex = 1, explanation = "a.taux crée un attribut d’instance. b consulte toujours l’attribut de classe égal à 2, tout comme Produit.taux.", hint = "Une affectation sur a n’est pas une affectation sur Produit.")
        ),
        objective = "Suivre la recherche de méthodes et distinguer attribut de classe et d’instance.",
        learningNotes = "Une sous-classe reprend les propriétés de sa classe parente et peut ajouter ou redéfinir des méthodes. Si Chien redéfinit parler, l'appel sur un chien utilise cette version ; une méthode absente est cherchée dans la hiérarchie parente. Le constructeur de la sous-classe peut appeler super().__init__ pour établir l'état commun avant d'ajouter ses propres données. isinstance(objet,Parent) accepte aussi les instances des sous-classes. Un attribut de classe appartient à la classe et peut être partagé, par exemple un compteur de créations ; un attribut self.age appartient à une instance. Affecter un nom d'attribut sur une instance peut masquer la valeur de classe sans changer celle des autres instances. Il faut suivre le propriétaire de chaque donnée.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/pages/lecture-19-inheritance/", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec19.pdf", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec19_code.py"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 19,
        sourceTitle = "Lecture 19: Inheritance",
        sessionKind = "lesson"
    )

    private fun lesson020() = Lesson(
        id = "mit_6_100l_2022_s020",
