            Exercise.CodeChallenge(id = "mit_6_100l_2022_s020_e01", prompt = "Quelle estimation donne ce modèle simplifié pour 90 minutes ?", codeSnippet = "minutes = 90\ntaux = 200\nprint(minutes/60 * taux)", options = listOf("18000", "200", "90", "300.0"), correctOptionIndex = 3, explanation = "90 minutes représentent 1.5 heure ; le taux pédagogique 200 donne 300.", hint = "Convertis les minutes en heures."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s020_e02", prompt = "Une valeur explicite égale à zéro doit-elle être remplacée ?", codeSnippet = "def depense(minutes, fournie=None):\n    if fournie is None:\n        return minutes/60 * 200\n    return fournie\nprint(depense(60, 0))", options = listOf("None", "60", "0", "200.0"), correctOptionIndex = 2, explanation = "Le test is None est faux pour 0. La valeur explicitement fournie est conservée.", hint = "Une valeur absente et une valeur nulle sont différentes."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s020_e03", prompt = "Quelle conception évite de recopier la gestion des heures dans chaque activité ?", options = listOf("Une méthode sans paramètres ni attributs pour toutes les durées.", "Une classe commune avec des sous-classes pour les propriétés spécifiques.", "Une copie indépendante de tout le code pour chaque activité.", "Un nom de variable unique pour toutes les séances."), correctOptionIndex = 1, explanation = "Les heures et la durée sont communes ; le dénivelé ou la nage peuvent être ajoutés dans les sous-classes.", hint = "Sépare les responsabilités partagées des différences."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s020_e04", prompt = "Quels attributs l’objet de course possède-t-il après initialisation ?", codeSnippet = "class Seance:\n    def __init__(self, minutes):\n        self.minutes = minutes\nclass Course(Seance):\n    def __init__(self, minutes, denivele):\n        super().__init__(minutes)\n        self.denivele = denivele\ns = Course(45, 120)\nprint(s.minutes, s.denivele)", options = listOf("45 120", "120 45", "0 120", "45 0"), correctOptionIndex = 0, explanation = "super initialise minutes à 45, puis le constructeur de Course initialise denivele à 120.", hint = "Le constructeur spécialisé complète l’état commun.")
        ),
        objective = "Séparer données communes, estimation et spécialisation d’un entraînement.",
        learningNotes = "Le suivi d'entraînements rassemble plusieurs notions : dates de début et de fin, durée, dépense estimée et activités spécialisées. Le support construit une classe Workout commune puis des sous-classes pour les particularités d'une course ou d'une autre activité. Une estimation au taux de 200 unités par heure pour 90 minutes donne 200*90/60=300 ; cette règle pédagogique n'est pas une mesure physiologique. Une valeur explicitement fournie peut remplacer l'estimation. Il faut alors distinguer None, qui signale l'absence de donnée, de zéro, qui reste une valeur fournie. Un constructeur enfant réutilise l'initialisation commune, puis ajoute par exemple le dénivelé. Des accesseurs bien définis permettent à un traitement commun de manipuler plusieurs activités sans dépendre de leur représentation interne.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/pages/lecture-20-fitness-tracker-object-oriented-programming-example/", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec20.pdf", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec20_code.zip"),
        requiresPreviousLesson = true,
