            Exercise.CodeChallenge(id = "mit_6_100l_2022_s021_e01", prompt = "En comptant seulement les augmentations de total, combien d’opérations sont réalisées ?", codeSnippet = "total = 0\nfor i in range(4):\n    for j in range(4):\n        total += 1\nprint(total)", options = listOf("8", "20", "16", "4"), correctOptionIndex = 2, explanation = "Chaque valeur de i déclenche quatre augmentations et il y a quatre valeurs de i : 4*4=16.", hint = "L’unité demandée n’inclut pas les tests des boucles."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s021_e02", prompt = "Si le coût exact est n² additions, quel facteur produit le passage de n à 3n ?", options = listOf("27", "9", "3", "6"), correctOptionIndex = 1, explanation = "(3n)²/n²=9. Ce facteur décrit le modèle d’opérations, pas une garantie de durée réelle.", hint = "Élève aussi le facteur multiplicatif au carré."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s021_e03", prompt = "Deux machines donnent des temps différents pour le même programme. Quelle comparaison isole mieux la croissance algorithmique ?", options = listOf("Comparer le nombre d’opérations selon n dans un modèle explicite.", "Conclure que le plus petit temps prouve toujours le meilleur algorithme.", "Ignorer la taille de l’entrée.", "Additionner les fréquences des processeurs."), correctOptionIndex = 0, explanation = "Un modèle annoncé sépare la croissance du travail des constantes liées à la machine ; il complète les mesures pratiques.", hint = "Cherche une quantité liée aux étapes de l’algorithme.")
        ),
        objective = "Définir une unité de coût et distinguer mesure réelle et croissance.",
        learningNotes = "Chronométrer un programme renseigne sur une exécution concrète, mais le résultat varie avec la machine, les autres tâches et l'implémentation. Compter des opérations permet d'exprimer le travail en fonction d'une taille d'entrée. Il faut annoncer ce que l'on compte : si l'unité est une addition dans l'accumulateur, une boucle range(n) en fait n et deux boucles imbriquées de n tours en font n². Cela ne compte pas encore tous les tests ou affectations du programme. Une conversion de température par une formule fixe demande le même nombre d'opérations dans ce modèle élémentaire. Comparer plusieurs tailles révèle une tendance ; une seule durée sur une petite entrée ne suffit pas pour déterminer la croissance d'un algorithme.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/pages/lecture-21-timing-programs-counting-operations/", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec21.pdf", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec21_code.py"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 21,
        sourceTitle = "Lecture 21: Timing Programs, Counting Operations",
        sessionKind = "lesson"
    )

    private fun lesson022() = Lesson(
        id = "mit_6_100l_2022_s022",
        title = "Lire les bornes O et Θ",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s022_e01", prompt = "Quel ordre serré correspond à T(n)=7n²+3n+8 ?", options = listOf("Θ(1)", "Θ(n²)", "Θ(n)", "Θ(log n)"), correctOptionIndex = 1, explanation = "Le terme quadratique domine ; les rapports des termes linéaire et constant à n² tendent vers zéro.", hint = "Repère le terme qui croît le plus vite."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s022_e02", prompt = "Pour T(n)=4n+7, quelle affirmation distingue correctement les deux notations ?", options = listOf("T est Θ(n) et O(n²).", "T est Θ(n²) et n’est pas O(n).", "T est Θ(1).", "T n’admet aucune borne supérieure."), correctOptionIndex = 0, explanation = "La borne quadratique est valable mais non serrée. L’ordre exact de croissance est linéaire.", hint = "O n’exige pas une borne optimale."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s022_e03", prompt = "Sur cette recherche linéaire, combien d’éléments sont examinés pour une cible absente ?", codeSnippet = "L = [2, 4, 6, 8, 10]\nexamines = 0\nfor x in L:\n    examines += 1\n    if x == 7:\n        break\nprint(examines)", options = listOf("0", "1", "4", "5"), correctOptionIndex = 3, explanation = "Aucune égalité ne déclenche break ; les cinq éléments sont examinés.", hint = "L’absence force le parcours complet."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s022_e04", prompt = "Une recherche dichotomique conserve une moitié de 1024 candidats à chaque étape. Après combien de divisions en reste-t-il un ?", options = listOf("32", "1024", "10", "5"), correctOptionIndex = 2, explanation = "1024=2^10, donc 1024/2^10=1. Il s’agit du nombre de divisions du domaine, pas de toutes les instructions Python.", hint = "Cherche la puissance de deux égale à 1024.")
        ),
        objective = "Distinguer borne supérieure, ordre serré et cas de recherche.",
        learningNotes = "L'analyse asymptotique décrit la croissance quand la taille devient grande, dans un modèle où certaines opérations sont élémentaires. O(g(n)) donne une borne supérieure à un facteur constant près ; Θ(g(n)) encadre le coût à la fois au-dessus et au-dessous. Ainsi 4n+7 est Θ(n) et aussi O(n²), mais Θ(n²) serait trop fort. Une recherche linéaire peut réussir au premier élément ; son pire cas visite toute la liste. Une recherche dichotomique par indices divise un intervalle ordonné en deux et prend un nombre logarithmique d'étapes au pire cas. Son contrat exige une liste triée ; le coût d'un éventuel tri préalable appartient au bilan. Les constantes comptent en pratique, même si la notation asymptotique les omet.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/pages/lecture-22-big-oh-and-theta/", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec22.pdf", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec22_code.py"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 22,
        sourceTitle = "Lecture 22: Big Oh and Theta",
        sessionKind = "lesson"
    )

    private fun lesson023() = Lesson(
        id = "mit_6_100l_2022_s023",
        title = "Reconnaître les familles de complexité",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s023_e01", prompt = "Combien de tours du corps intérieur sont effectués ?", codeSnippet = "tours = 0\nfor i in range(5):\n    for j in range(i):\n        tours += 1\nprint(tours)", options = listOf("10", "5", "15", "25"), correctOptionIndex = 0, explanation = "Les bornes intérieures valent 0,1,2,3,4 ; leur somme vaut 10.", hint = "Dresse la liste des tailles des boucles intérieures."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s023_e02", prompt = "Deux parcours successifs de n éléments, avec travail constant par élément, ont quel ordre serré total ?", options = listOf("Θ(n²)", "Θ(log n)", "Θ(2^n)", "Θ(n)"), correctOptionIndex = 3, explanation = "n+n=2n. Une somme de coûts linéaires reste linéaire ; les parcours ne sont pas imbriqués.", hint = "Additionne les coûts au lieu de les multiplier."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s023_e03", prompt = "Combien de sous-ensembles possède une collection de six éléments distincts ?", options = listOf("36", "720", "64", "12"), correctOptionIndex = 2, explanation = "Chaque élément offre deux choix indépendants : présent ou absent. Le total est 2^6=64.", hint = "Compte les décisions binaires, y compris l’ensemble vide."),
            Exercise.CodeChallenge(id = "mit_6_100l_2022_s023_e04", prompt = "Combien de divisions par deux ce programme effectue-t-il ?", codeSnippet = "n, tours = 32, 0\nwhile n > 1:\n    n //= 2\n    tours += 1\nprint(tours)", options = listOf("32", "5", "4", "16"), correctOptionIndex = 1, explanation = "Les états sont 32,16,8,4,2,1. Cinq divisions amènent à 1.", hint = "Compte les transitions entre les états.")
        ),
        objective = "Relier structure des boucles, copies et nombre de résultats.",
        learningNotes = "La forme du code aide à déterminer son coût, mais il faut lire les bornes et le travail interne. Deux boucles successives de n tours donnent un coût linéaire ; deux boucles imbriquées de n tours donnent un coût quadratique. Si la borne intérieure vaut i, le nombre de tours est 0+1+...+(n-1)=n(n-1)/2, encore Θ(n²). Une division répétée par deux conduit à un nombre logarithmique d'étapes. Énumérer tous les sous-ensembles d'une collection de n éléments produit 2**n résultats. Si chaque sous-ensemble est matérialisé comme une liste, copier leurs éléments ajoute du travail : on ne peut assimiler chaque résultat à une opération constante. La taille de sortie peut elle-même imposer un coût considérable.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/pages/lecture-23-complexity-classes-examples/", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec23.pdf", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec23_code.py"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 23,
        sourceTitle = "Lecture 23: Complexity Classes Examples",
        sessionKind = "lesson"
    )

    private fun lesson024() = Lesson(
        id = "mit_6_100l_2022_s024",
        title = "Trier et amortir un travail préalable",
