            Exercise.CodeChallenge(id = "mit_6_100l_2022_s024_e01", prompt = "Quel état suit une seule passe de bulles de gauche à droite ?", codeSnippet = "L = [4, 2, 3, 1]\nfor j in range(1, len(L)):\n    if L[j-1] > L[j]:\n        L[j-1], L[j] = L[j], L[j-1]\nprint(L)", options = listOf("[1, 2, 3, 4]", "[2, 4, 1, 3]", "[4, 3, 2, 1]", "[2, 3, 1, 4]"), correctOptionIndex = 3, explanation = "4 échange successivement avec 2, puis 3, puis 1 ; il atteint la dernière position. Les autres éléments ne sont pas encore tous triés.", hint = "Le grand élément continue son déplacement au tour suivant."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s024_e02", prompt = "Quel invariant explique la fusion de deux listes déjà triées ?", options = listOf("Chaque liste doit être mélangée avant comparaison.", "Les deux têtes sont nécessairement égales.", "Le plus petit des deux éléments de tête est le prochain élément global.", "Il faut toujours prendre l’élément de gauche."), correctOptionIndex = 2, explanation = "Tout élément restant de chaque liste est au moins aussi grand que sa tête. Comparer les deux têtes suffit donc.", hint = "Utilise l’ordre interne de chacune des deux listes."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s024_e03", prompt = "Un modèle compte 100 opérations pour trier, puis 5 par recherche, contre 25 par recherche directe. Pour 10 recherches, quel bilan obtient-on ?", options = listOf("100 contre 50", "150 contre 250", "105 contre 25", "500 contre 250"), correctOptionIndex = 1, explanation = "Le premier coût est 100+10*5=150 ; le second vaut 10*25=250. Ici le prétraitement est amorti.", hint = "Sépare coût initial et coût par requête."),
            Exercise.MultipleChoice(id = "mit_6_100l_2022_s024_e04", prompt = "Pourquoi un tri par mélanges aléatoires n’a-t-il pas de pire nombre fini de mélanges garanti ?", options = listOf("Une suite de mélanges peut continuer à produire des permutations non triées.", "Toute permutation est déjà triée.", "Le premier mélange trie toujours.", "Le nombre de mélanges est exactement n."), correctOptionIndex = 0, explanation = "Même si le tri finit avec probabilité un dans un modèle usuel, un nombre arbitrairement grand d’échecs reste possible.", hint = "Une forte probabilité de finir n’est pas une borne déterministe.")
        ),
        objective = "Suivre une passe de tri et comparer coûts simples et répétés.",
        learningNotes = "Trier une collection peut accélérer des recherches ultérieures, mais son coût initial doit être compté. Pour une seule recherche, un tri suivi d'une dichotomie peut coûter davantage qu'un parcours direct ; pour beaucoup de recherches, ce coût peut être amorti. Le tri à bulles échange des voisins mal ordonnés : une passe de gauche à droite pousse le maximum vers la fin. Le tri par sélection place successivement le minimum de la partie restante. Leurs versions usuelles ont un pire coût quadratique. Le tri fusion sépare, trie récursivement puis fusionne deux listes ordonnées ; n éléments traités sur environ log n niveaux donnent Θ(n log n). Mélanger au hasard jusqu'à obtenir l'ordre ne fournit aucune borne finie garantie sur le nombre d'essais.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/pages/lecture-24-sorting-algorithms/", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec24.pdf", "https://ocw.mit.edu/courses/6-100l-introduction-to-cs-and-programming-using-python-fall-2022/mit6_100l_f22_lec24_code.py"),
